#!/usr/bin/env node
// Entry point for the `devc` binary.
//
// Deliberately thin and hand-written (not generated by tsc) so that npm's bin
// shim points at a stable path that never moves when the build output layout
// changes. Everything below `dist/` is compiled.
//
// Source maps are enabled here rather than through a NODE_OPTIONS env var or a
// shebang flag: npm rewrites shebangs on Windows into .cmd shims that drop
// extra node arguments, so the flag form would silently stop working there.
// Without this, the failure reporter points at dist/*.js line numbers.
process.setSourceMapsEnabled(true)

const { main } = await import('../dist/src/cli.js')
process.exitCode = await main(process.argv.slice(2))
